    (forall b, In b LBs2 -> In b LB') ->
    (forall A n, In (A, n) (umap_blocks 24 bl2 bc2 ents2) -> In (A, n) (lbl LBs2)) ->
    (forall b, In b LB' -> In b LB) ->
    TS s' LB' bl2 bc2 ents2 LBs2 m'.
