  Lemma TS_munchB : forall s LB bl2 bc2 ents2 LBs2 m m' W q A N,
    TS s LB bl2 bc2 ents2 LBs2 m -> munch W m m' -> wmono asegs m m' -> mem_inv asegs m' ->
    Forall (fun iv => wT iv \/ (A <= fst iv /\ snd iv <= A + N)) W ->
    Permutation LB ((LB0 ++ LBs2) ++ [(q, A, N)]) ->
    (bc2 <> 0 -> bl2 + 8 * bc2 <= 2 ^ 47) -> (forall p k v, In (p, (k, v)) ents2 -> p + 24 <= 2 ^ 47) ->
    (bc2 <> 0 -> 0 <= bl2) -> (forall p k v, In (p, (k, v)) ents2 -> 0 <= p) -> 0 <= bc2 ->
    TS s LB bl2 bc2 ents2 LBs2 m'.
