      apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|];
      apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|];
      apply Forall_cons; [cbn [kentry_ok]; unfold estart, elenZ; evs; rewrite !u64_of_Z by lia; cbn [a_off]; lia|];
      apply Forall_cons; [eapply (kwr_of_wr_at asegs _ _ _ 40); [exact (proj2 H1) | rwc_norm | unfold elenZ; rwc_norm | unfold elenZ; evs; rewrite u64_of_Z by lia; lia]|];
      apply Forall_cons; [eapply (kwr_of_wr_at asegs _ _ _ 40); [exact (proj2 H2) | rwc_norm | unfold elenZ; rwc_norm | unfold elenZ; evs; rewrite u64_of_Z by lia; lia]|];
      apply Forall_cons; [eapply (kword_of_rw_cells asegs _ _ _ _ 0%nat); [exact C20 | reflexivity | reflexivity | lia | rwc_norm | lia | cbn; lia | reflexivity]|];
      apply Forall_cons; [eapply (kword_of_rw_cells asegs _ _ _ _ 0%nat); [exact C10 | reflexivity | reflexivity | lia | rwc_norm | lia | cbn; lia | reflexivity]|];
      apply Forall_cons; [eapply (kword_of_rw_cells asegs _ _ _ _ 0%nat); [exact C18 | reflexivity | reflexivity | lia | rwc_norm | lia | cbn; lia | reflexivity]|];
      apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|];
      know_tac.
