  Lemma nodes_exist : forall (ents : list (Z * (Z * Z))) (LBn : list block) (m : mem),
    lbl LBn = map (fun e => (fst e, 24)) ents ->
    HRep.chain ASEGS m ents -> lb_own LBn m ->
    (forall p k v, In (p, (k, v)) ents -> addressable m p 24 /\ AIMG_TOP <= p /\ p + 24 <= 2 ^ 47) ->
    exists ns, nodes_okA LBn m ns /\ map fst ns = map fst ents.
Proof.
